struct Baseline {live::JointVector offset{};live::BoundaryId boundary{};bool valid=false;};
inline void match(const live::ObservedActual&a,const live::AcceptedCommandHistory&c,const live::ProgressHistory&p){need(a.completed&&a.current_contact_free&&c.completed&&p.completed&&a.boundary.completed_tick==c.boundary.completed_tick&&a.boundary.completed_command_sequence==c.boundary.completed_command_sequence&&a.boundary.completed_tick==p.boundary.completed_tick&&a.boundary.completed_command_sequence==p.boundary.completed_command_sequence&&a.observation_id==c.observation_id&&a.observation_id==p.observation_id&&a.transaction_id==c.transaction_id&&a.transaction_id==p.transaction_id&&!a.observation_id.empty()&&a.observation_id.size()<=256&&!a.transaction_id.empty()&&a.transaction_id.size()<=256,"same completed actual/command/progress identity and boundary");for(int j=0;j<7;++j)need(std::isfinite(a.q[j])&&std::isfinite(a.v[j])&&std::isfinite(c.C[j])&&std::isfinite(c.w[j])&&std::isfinite(c.previous_alpha[j]),"finite genuine q/v/C/w/history");}
inline Baseline baseline(const live::ObservedActual&a,const live::AcceptedCommandHistory&c,const live::ProgressHistory&p){match(a,c,p);need(a.boundary.completed_tick==0&&a.boundary.completed_command_sequence==0,"baseline only genuine session task-start boundary0");Baseline b;b.boundary=a.boundary;for(int j=0;j<7;++j){need(std::abs(a.v[j])<=1e-4,"finite near-rest measured task-start baseline, not exact equilibrium");b.offset[j]=c.C[j]-a.q[j];need(std::isfinite(b.offset[j]),"finite measured offset");}b.valid=true;return b;}
inline live::JointVector targets(const live::ObservedActual&a,const live::AcceptedCommandHistory&c,const live::ProgressHistory&p,const Baseline&b){match(a,c,p);need(b.valid&&b.boundary.completed_tick==0&&b.boundary.completed_command_sequence==0,"same session measured baseline required");live::JointVector t{};for(int j=0;j<7;++j){t[j]=a.q[j]+b.offset[j]-physical_feedback_seconds*a.v[j];need(std::isfinite(b.offset[j])&&std::isfinite(t[j]),"finite physical feedback target, no state or control clipping");}return t;}
struct Diagnostics {std::array<std::uint64_t,8>selected{},attempted{};std::array<double,8>pulse1{},pulse2{},terminal_rate{};std::uint64_t total_attempts=0;bool complete=false;};
