struct Attempt {std::uint64_t channel=0,family=0,reason=0,cell=0,step=0;double pulse1=0,pulse2=0,score=0,last_rate=0,last_position=0,max_jerk=0,observed=0,bound=0;};
inline void integrate(const std::array<double,20>&u,double&w,double&C){for(int k=0;k<20;++k)for(int n=0;n<old::mesh[k];++n){w=w+.004*u[k];C=C+.004*w;}}
inline Check doublehat(double w,double prior,double C,double target,int L,int M,std::array<double,20>&u,double&p1,double&p2){std::array<double,20>base{},a{},b{};const int peak=(M-1)/2;for(int k=0;k<20;++k){base[k]=prior*std::max(0.,1.-double(k+1)/L);a[k]=k<M?std::min(double(k+1)/(peak+1),double(M-k)/(M-peak)):0.;}for(int k=0;k<19;++k)b[k]=a[18-k];double bw=w,bc=C,wa=0,ca=0,wb=0,cb=0;integrate(base,bw,bc);integrate(a,wa,ca);integrate(b,wb,cb);const double det=wa*cb-wb*ca,scale=std::abs(wa*cb)+std::abs(wb*ca);Check fail;fail.rate=w;fail.position=C;if(!std::isfinite(det)||!(scale>0)||std::abs(det)<=1e-10*scale){fail.reason=11;fail.observed=det;fail.bound=1e-10*scale;return fail;}p1=((-bw)*cb-(target-bc)*wb)/det;p2=(wa*(target-bc)-ca*(-bw))/det;if(!std::isfinite(p1)||!std::isfinite(p2)){fail.reason=1;return fail;}for(int k=0;k<20;++k)u[k]=base[k]+p1*a[k]+p2*b[k];return fail;}
inline double firstProgressLower(double r,double first_b_offset,double old_lower){need(std::isfinite(r)&&r>0&&std::isfinite(first_b_offset)&&std::isfinite(old_lower),"finite genuine first-progress guard");return std::max(old_lower,std::nextafter((first_progress_floor-r)/(.004*.004)-first_b_offset/.004,-std::numeric_limits<double>::infinity()));}
inline bool strictFirstProgress(double r,double b){return std::isfinite(r)&&std::isfinite(b)&&std::nextafter(r+.004*b,-std::numeric_limits<double>::infinity())>=strict_first_progress_floor;}
template<class Emit> Diagnostics build(const live::ObservedActual&a,const live::AcceptedCommandHistory&cmd,const live::ProgressHistory&progress,const Baseline&b,const live::StaticDomainRanges&ranges,std::vector<live::NominalControl>&controls,Emit&&emit){need(controls.size()==20,"existing fixed20 nominal controls");const auto target=targets(a,cmd,progress,b);need(std::isfinite(progress.s)&&progress.s>=0&&progress.s<=1&&std::isfinite(progress.r)&&progress.r>0&&progress.r<=.2&&std::isfinite(progress.previous_b)&&std::abs(progress.previous_b)<=.5,"genuine finite positive progress history");for(int j=0;j<7;++j)need(cmd.C[j]>=ranges.cLower()[j]+.005&&cmd.C[j]<=ranges.cUpper()[j]-.005&&std::abs(cmd.w[j])<=.0625&&std::abs(cmd.previous_alpha[j])<=1.,"current original scalar domains");std::array<live::NominalControl,20>next{};Diagnostics d;
 for(int ch=0;ch<8;++ch){const bool prog=ch==7;const double rate=prog?progress.r:cmd.w[ch],prior=prog?progress.previous_b:cmd.previous_alpha[ch],pos=prog?progress.s:cmd.C[ch];bool found=false;double best_score=std::numeric_limits<double>::infinity();std::uint64_t id=0;
 auto record=[&](std::uint64_t family,const std::array<double,20>&u,double p1,double p2,Check proof,bool warm){need(d.total_attempts<1080&&family<(prog?149:133),"old1080 total/133joint149progress preattempt bound");double score=0;if(!proof.reason&&!prog&&!warm&&std::abs(proof.position-target[ch])>1e-12){proof.reason=13;proof.observed=std::abs(proof.position-target[ch]);proof.bound=1e-12;}if(!proof.reason&&prog&&rate+.004*u[0]<first_progress_floor){proof.reason=12;proof.cell=proof.step=0;proof.observed=rate+.004*u[0];proof.bound=first_progress_floor;}if(!proof.reason&&!prog){score=std::abs(pos+.004*(rate+.004*u[0])-target[ch]);if(!std::isfinite(score)){proof.reason=1;proof.observed=score;}}
 ++d.total_attempts;++d.attempted[ch];emit(Attempt{static_cast<std::uint64_t>(ch),family,proof.reason,proof.cell,proof.step,p1,p2,score,proof.rate,proof.position,proof.max_jerk,proof.observed,proof.bound});if(!proof.reason&&(!found||(!prog&&score<best_score))){found=true;best_score=score;d.selected[ch]=family;d.pulse1[ch]=p1;d.pulse2[ch]=p2;d.terminal_rate[ch]=proof.rate;for(int k=0;k<20;++k){if(prog)next[k].b=u[k];else next[k].alpha[ch]=u[k];}}};
 for(int L:old::lengths){for(int M:old::supports){std::array<double,20>u{};double p1=0,p2=0;Check proof;if(prog){u=old::family(rate,prior,nominal_progress_target,L,M,p1);proof=old::check(u,rate,prior,pos,true,0,0,nominal_progress_target);}else{proof=doublehat(rate,prior,pos,target[ch],L,M,u,p1,p2);if(!proof.reason)proof=old::check(u,rate,prior,pos,false,ranges.cLower()[ch],ranges.cUpper()[ch],0.);}record(id++,u,p1,p2,proof,false);if(prog&&found)break;}if(prog&&found)break;}
 if(prog&&!found)for(int e=0;e<16;++e){double p1=0;Check proof;proof.rate=rate;proof.position=pos;const auto u=old::progressEnvelope(rate,prior,nominal_progress_target,e,p1,proof);if(!proof.reason)proof=old::check(u,rate,prior,pos,true,0,0,nominal_progress_target);record(132+e,u,p1,0,proof,false);if(found)break;}
 if(!found){std::array<double,20>u{};for(int k=0;k<20;++k)u[k]=prog?controls[k].b:controls[k].alpha[ch];record(prog?148:132,u,0,0,old::check(u,rate,prior,pos,prog,prog?0:ranges.cLower()[ch],prog?0:ranges.cUpper()[ch],0.,true),true);}need(found,"finite original133joint149progress current-state families exhausted, all failures retained");
 }for(int k=0;k<20;++k)controls[k]=next[k];d.complete=true;return d;}
